# builder/gen_ch25_p2.py
# -*- coding: utf-8 -*-

exercises = [{'num': 24, 'title': 'Логирующий Middleware для HTTP-сервера и клиента (Request Metrics)', 'task': 'Реализуйте middleware для логирования всех входящих запросов (метод, URL, длительность выполнения).', 'theory': 'Паттерн HTTP Middleware (Цепочка обязанностей): функция-обёртка перехватывает запрос, фиксирует временную метку `t0 := time.Now()`, делегирует выполнение следующему хендлеру и логирует метод, путь, статус и время выполнения `time.Since(t0)`.', 'step_by_step': '1. Создадим `LoggingMiddleware(next http.Handler) http.Handler`.\n2. Обернем `http.ResponseWriter` для перехвата статус-кода.\n3. Выполним тестовые GET и POST запросы.\n4. Выведем журнал метрик в консоль.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\ntype statusRecorder struct {\n\thttp.ResponseWriter\n\tstatusCode int\n}\n\nfunc (r *statusRecorder) WriteHeader(code int) {\n\tr.statusCode = code\n\tr.ResponseWriter.WriteHeader(code)\n}\n\nfunc LoggingMiddleware(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tt0 := time.Now()\n\t\trec := &statusRecorder{ResponseWriter: w, statusCode: http.StatusOK}\n\n\t\tnext.ServeHTTP(rec, r)\n\n\t\tduration := time.Since(t0)\n\t\tfmt.Printf("[HTTP ACCESS LOG] %-6s %-15s -> Status: %d | Latency: %v\\n", \n\t\t\tr.Method, r.URL.Path, rec.statusCode, duration.Round(time.Microsecond))\n\t})\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/api/v1/health", func(w http.ResponseWriter, r *http.Request) {\n\t\ttime.Sleep(5 * time.Millisecond)\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte("OK"))\n\t})\n\tmux.HandleFunc("/api/v1/orders", func(w http.ResponseWriter, r *http.Request) {\n\t\ttime.Sleep(12 * time.Millisecond)\n\t\tw.WriteHeader(http.StatusCreated)\n\t\t_, _ = w.Write([]byte(`{"order_id": 99}`))\n\t})\n\n\t// Оборачиваем роутер в middleware\n\tloggedHandler := LoggingMiddleware(mux)\n\tts := httptest.NewServer(loggedHandler)\n\tdefer ts.Close()\n\n\t// Тестовые вызовы\n\t_, _ = http.Get(ts.URL + "/api/v1/health")\n\t_, _ = http.Post(ts.URL+"/api/v1/orders", "application/json", nil)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [HTTP ACCESS LOG] GET    /api/v1/health  -> Status: 200 | Latency: 5ms\n# [HTTP ACCESS LOG] POST   /api/v1/orders  -> Status: 201 | Latency: 12ms'}], 'under_the_hood': 'Встроенная структура `statusRecorder` перехватывает вызов `WriteHeader`, сохраняя код ответа для логов.', 'pitfalls': 'Если хендлер не вызывает `WriteHeader`, статус по умолчанию равен 200 OK (инициализируйте `rec.statusCode = http.StatusOK`).', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем нужна структура statusRecorder при написании Middleware в Go?»\n**Ответ:** Стандартный интерфейс `http.ResponseWriter` не имеет метода для чтения уже записанного статус-кода. Обертка `statusRecorder` перехватывает метод `WriteHeader(code)` и сохраняет его в поле структуры для последующего логирования и сбора метрик Prometheus.'}, {'num': 25, 'title': 'Установка кастомных HTTP-заголовков User-Agent и Authorization', 'task': 'Напиши **HTTP-клиент с кастомными заголовками**: `req.Header.Set("User-Agent", "MyBot/1.0")`, `req.Header.Set("Authorization", "Bearer ...")`. Покажи, что `http.DefaultClient` использует дефолтный User-Agent.', 'theory': 'Заголовки сетевой идентификации: `http.DefaultClient` отправляет заголовок `User-Agent: Go-http-client/1.1` (или 2.0). Большинство внешних Cloudflare/WAF и REST API серверов (GitHub API, Cloudflare) блокируют запросы со стандартным User-Agent Go, требуя явного указания названия сервиса.', 'step_by_step': '1. Поднимем сервер, инспектирующий `User-Agent` и `Authorization`.\n2. Отправим запрос со стандартным клиентом (дефолтный UA).\n3. Отправим запрос с кастомными заголовками.\n4. Проверим разницу.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Printf(" [Server Inspection] Path: %-12s | User-Agent: %s\\n", \n\t\t\tr.URL.Path, r.Header.Get("User-Agent"))\n\t\tw.WriteHeader(http.StatusOK)\n\t}))\n\tdefer ts.Close()\n\n\t// 1. Дефолтный запрос через http.Get\n\tresp1, _ := http.Get(ts.URL + "/default")\n\tresp1.Body.Close()\n\n\t// 2. Кастомный запрос с кастомными заголовками\n\treq, _ := http.NewRequest(http.MethodGet, ts.URL+"/custom", nil)\n\treq.Header.Set("User-Agent", "EnterpriseBot/2.4 (Linux; x86_64)")\n\treq.Header.Set("Authorization", "Bearer JWT_SECRET_TOKEN_123")\n\treq.Header.Set("X-Request-ID", "REQ-998811")\n\n\tclient := &http.Client{}\n\tresp2, _ := client.Do(req)\n\tresp2.Body.Close()\n\n\tfmt.Println("[Client] Запросы с заголовками успешно отправлены.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  [Server Inspection] Path: /default     | User-Agent: Go-http-client/1.1\n#  [Server Inspection] Path: /custom      | User-Agent: EnterpriseBot/2.4 (Linux; x86_64)\n# [Client] Запросы с заголовками успешно отправлены.'}], 'under_the_hood': 'Если заголовок `User-Agent` не задан явно, рантайм `net/http` автоматически подставляет константу `Go-http-client/1.1`.', 'pitfalls': 'Сервисы вроде GitHub API возвращают `403 Forbidden`, если `User-Agent` отсутствует или равен дефолтному значению Go.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем микросервисы передают заголовок X-Request-ID (или Traceparent W3C)?»\n**Ответ:** Для распределенной трассировки (Distributed Tracing / OpenTelemetry): сквозной `X-Request-ID` передается через всю цепочку микросервисов (API Gateway -> Auth -> Billing -> DB), позволяя найти все логи одного пользовательского запроса в Jaeger/Grafana Tempo.'}, {'num': 26, 'title': 'Принудительный таймаут HTTP-запроса через context.WithTimeout', 'task': 'Напиши **HTTP-клиент с `context.WithTimeout`**: `ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)`. Передай в `req.WithContext(ctx)`. Покажи, что запрос прерывается при таймауте.', 'theory': 'Контекстный таймаут запроса: `context.WithTimeout` передает сигнал отмены на уровень сетевого сокета при превышении лимита времени, мгновенно разблокируя клиентскую горутину.', 'step_by_step': '1. Сервер имитирует долгую обработку (150 мс).\n2. Клиент настраивает `context.WithTimeout` на 30 мс.\n3. Выполняет `client.Do(req)`.\n4. Перехватывает ошибку таймаута.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\ttime.Sleep(150 * time.Millisecond) // Долгий запрос\n\t\tw.WriteHeader(http.StatusOK)\n\t}))\n\tdefer ts.Close()\n\n\tctx, cancel := context.WithTimeout(context.Background(), 30*time.Millisecond)\n\tdefer cancel()\n\n\treq, err := http.NewRequestWithContext(ctx, http.MethodGet, ts.URL, nil)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\n\tclient := &http.Client{}\n\tfmt.Println("[Client] Отправка запроса с context таймаутом 30 мс...")\n\t_, err = client.Do(req)\n\n\tif err != nil {\n\t\tfmt.Printf("[Client Safety] Запрос прерван по контексту: %v\\n", err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client] Отправка запроса с context таймаутом 30 мс...\n# [Client Safety] Запрос прерван по контексту: Get "http://127.0.0.1:...": context deadline exceeded'}], 'under_the_hood': '`req.WithContext` или `http.NewRequestWithContext` связывает сетевой дескриптор с таймером в рантайме Go.', 'pitfalls': 'Функция `req.WithContext(ctx)` возвращает поверхностную копию `*http.Request` с новым контекстом, не мутируя исходный запрос.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие http.NewRequestWithContext от req.WithContext?»\n**Ответ:** `http.NewRequestWithContext` создает новый объект запроса сразу с заданным контекстом. `req.WithContext` делает поверхностную копию существующего `*http.Request`, заменяя только поле `ctx` (полезно при пробрасывании контекста в middleware).'}, {'num': 27, 'title': 'Настройка HTTP и SOCKS5 прокси-сервера через http.Transport ProxyURL', 'task': 'Напиши **HTTP-прокси клиент**: `proxyURL, _ := url.Parse("http://proxy:8080"); transport := &http.Transport{Proxy: http.ProxyURL(proxyURL)}; client := &http.Client{Transport: transport}`.', 'theory': 'Проксирование сетевого HTTP/HTTPS трафика: поле `Transport.Proxy` принимает функцию `func(*http.Request) (*url.URL, error)`. Функция `http.ProxyURL(proxyURL)` направляет все TCP-соединения через указанный Forward/Corporate Proxy сервер.', 'step_by_step': '1. Поднимем локальный тестовый HTTP Forward Proxy сервер.\n2. Сконфигурируем `http.Transport{Proxy: http.ProxyURL(proxy)}`.\n3. Выполним запрос через прокси.\n4. Убедимся, что запрос прошел через прокси-ноду.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"net/url"\n)\n\nfunc main() {\n\t// 1. Целевой Origin сервер\n\toriginServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte("ORIGIN_DATA_SERVED"))\n\t}))\n\tdefer originServer.Close()\n\n\t// 2. HTTP Forward Proxy сервер\n\tproxyHits := 0\n\tproxyServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tproxyHits++\n\t\tfmt.Printf("[Proxy Server] Перехвачен запрос к: %s\\n", r.RequestURI)\n\n\t\t// Делегируем запрос на целевой сервер\n\t\toutReq, _ := http.NewRequest(r.Method, r.RequestURI, r.Body)\n\t\tresp, err := http.DefaultTransport.RoundTrip(outReq)\n\t\tif err != nil {\n\t\t\thttp.Error(w, err.Error(), http.StatusBadGateway)\n\t\t\treturn\n\t\t}\n\t\tdefer resp.Body.Close()\n\n\t\tw.WriteHeader(resp.StatusCode)\n\t\t_, _ = io.Copy(w, resp.Body)\n\t}))\n\tdefer proxyServer.Close()\n\n\t// 3. Клиент с настройкой ProxyURL\n\tproxyURL, err := url.Parse(proxyServer.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\n\ttransport := &http.Transport{\n\t\tProxy: http.ProxyURL(proxyURL),\n\t}\n\tclient := &http.Client{Transport: transport}\n\n\tresp, err := client.Get(originServer.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tbody, _ := io.ReadAll(resp.Body)\n\tfmt.Printf("[Client Response] %s (Всего через прокси: %d)\\n", string(body), proxyHits)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Proxy Server] Перехвачен запрос к: http://127.0.0.1:...\n# [Client Response] ORIGIN_DATA_SERVED (Всего через прокси: 1)'}], 'under_the_hood': 'Для HTTPS сайтов клиент отправляет прокси HTTP-команду `CONNECT target.host:443 HTTP/1.1`, открывая TLS-туннель.', 'pitfalls': 'По умолчанию `http.ProxyFromEnvironment` считывает переменные окружения `HTTP_PROXY`, `HTTPS_PROXY` и `NO_PROXY`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как работает метод HTTP CONNECT при проксировании HTTPS соединений?»\n**Ответ:** Клиент отправляет обычному HTTP-прокси команду `CONNECT host:443 HTTP/1.1`. Прокси открывает сырой TCP-сокет к целевому хосту и связывает сокет клиента с сокетом целевого сервера (двунаправленный байтовый пайп). Клиент инициирует TLS Handshake напрямую с целевым сервером внутри этого туннеля (End-to-End Encryption).'}, {'num': 28, 'title': 'Архитектурный анализ рисков http.DefaultClient и создание безопасного клиента', 'task': '**Опасность `http.DefaultClient`**: Напишите комментарий-объяснение, почему использование стандартного `http.Get` или `http.DefaultClient` крайне опасно на высоконагруженном продакшене (подсказка: отсутствие таймаутов по умолчанию может привести к зависанию горутин при сетевых сбоях). Напишите код инициализации безопасного клиента `http.Client` с жестким таймаутом в 3 секунды.', 'theory': 'Инженерный анализ рисков `http.DefaultClient`:\n* `Timeout = 0` — при зависании стороннего сервиса горутины остаются в ожидании навсегда, исчерпывая память и вызывая каскадное падение кластера (Cascading Failure).\n* `MaxIdleConnsPerHost = 2` — разрушает Keep-Alive пул при нагрузке свыше 10 RPS.\n* `TLSHandshakeTimeout` не изолирован.', 'step_by_step': '1. Опишем production-grade конфигурацию клиента.\n2. Выставим жесткий таймаут 3 секунды.\n3. Настроим пулинг соединений.\n4. Протестируем клиент.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net"\n\t"net/http"\n\t"time"\n)\n\n// SafeProductionClient возвращает защищенный HTTP-клиент для микросервисов\nfunc SafeProductionClient() *http.Client {\n\treturn &http.Client{\n\t\tTimeout: 3 * time.Second, // Глобальный дедлайн на весь жизненный цикл запроса\n\t\tTransport: &http.Transport{\n\t\t\tDialContext: (&net.Dialer{\n\t\t\t\tTimeout:   1 * time.Second, // Таймаут на установку TCP 3-Way Handshake\n\t\t\t\tKeepAlive: 30 * time.Second,\n\t\t\t}).DialContext,\n\t\t\tMaxIdleConns:          200,              // Общий лимит свободных сокетов в пуле\n\t\t\tMaxIdleConnsPerHost:   50,               // Лимит сокетов на один микросервис\n\t\t\tIdleConnTimeout:       90 * time.Second, // Время жизни неактивного Keep-Alive сокета\n\t\t\tTLSHandshakeTimeout:   1 * time.Second,  // Таймаут TLS Negotiation\n\t\t\tExpectContinueTimeout: 1 * time.Second,\n\t\t},\n\t}\n}\n\nfunc main() {\n\tclient := SafeProductionClient()\n\tfmt.Printf("[Safe Client Ready] Timeout=%v, MaxIdlePerHost=%d\\n", \n\t\tclient.Timeout, client.Transport.(*http.Transport).MaxIdleConnsPerHost)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Safe Client Ready] Timeout=3s, MaxIdlePerHost=50'}], 'under_the_hood': 'Разделение таймаутов на уровне `DialContext`, `TLSHandshakeTimeout` и `client.Timeout` позволяет быстро диагностировать этап сбоя (DNS, TCP, TLS или обработка сервером).', 'pitfalls': 'Не пересоздавайте `SafeProductionClient()` внутри хендлеров; используйте синглтон.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое каскадный сбой (Cascading Failure) и как таймауты HTTP-клиента его предотвращают?»\n**Ответ:** Если сервис Б начинает медленно отвечать, вызывающий сервис А без таймаутов накапливает тысячи заблокированных горутин, исчерпывает пул потоков и память и падает. Следом падают сервисы, зависящие от А. Жесткие таймауты и Circuit Breaker обрывают зависшие вызовы, изолируя сбой.'}, {'num': 29, 'title': 'Структурированный POST-запрос с JSON телом и проверкой ответа', 'task': '**POST-запрос с отправкой JSON**: Создайте структуру `Post` с полями `Title`, `Body`, `UserID`. Сериализуйте её в JSON. Отправьте POST-запрос на тестовый URL с помощью `http.Post` или создав кастомный запрос через `http.NewRequest`. Убедитесь, что вы правильно установили заголовок `Content-Type: application/json`.', 'theory': 'Формирование REST POST запроса: сериализация структуры в JSON байты и передача через `bytes.NewBuffer` в `http.NewRequest`.', 'step_by_step': '1. Создадим структуру `Post { Title, Body, UserID }`.\n2. Сериализуем через `json.Marshal`.\n3. Создадим `http.NewRequest("POST", url, bytes.NewBuffer(payload))`.\n4. Установим `req.Header.Set("Content-Type", "application/json")`.\n5. Отправим запрос и распарсим ответ.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\ntype Post struct {\n\tTitle  string `json:"title"`\n\tBody   string `json:"body"`\n\tUserID int    `json:"userId"`\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tif r.Header.Get("Content-Type") != "application/json" {\n\t\t\thttp.Error(w, "Invalid Content-Type", http.StatusUnsupportedMediaType)\n\t\t\treturn\n\t\t}\n\n\t\tvar p Post\n\t\t_ = json.NewDecoder(r.Body).Decode(&p)\n\t\tw.WriteHeader(http.StatusCreated)\n\t\t_, _ = w.Write([]byte(fmt.Sprintf(`{"id": 204, "created_title": %q}`, p.Title)))\n\t}))\n\tdefer ts.Close()\n\n\tnewPost := Post{\n\t\tTitle:  "Основы HTTP-клиента в Go",\n\t\tBody:   "Разбор методов Do, Get, Post и пулинга соединений.",\n\t\tUserID: 7,\n\t}\n\n\tpayload, _ := json.Marshal(newPost)\n\treq, err := http.NewRequest(http.MethodPost, ts.URL+"/posts", bytes.NewBuffer(payload))\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\treq.Header.Set("Content-Type", "application/json")\n\n\tclient := &http.Client{}\n\tresp, err := client.Do(req)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\trespBytes, _ := io.ReadAll(resp.Body)\n\tfmt.Printf("[Post Response] Status=%d, Body=%s\\n", resp.StatusCode, string(respBytes))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Post Response] Status=201, Body={"id": 204, "created_title": "Основы HTTP-клиента в Go"}'}], 'under_the_hood': '`bytes.NewBuffer(payload)` передает срез байтов без дублирования памяти.', 'pitfalls': 'Не забывайте `defer resp.Body.Close()`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие bytes.NewReader от bytes.NewBuffer при передаче в http.NewRequest?»\n**Ответ:** `bytes.NewReader` реализует `io.Reader`, `io.Seeker` и `io.ReaderAt` (read-only), что позволяет транспорту автоматически определить `Content-Length`. `bytes.NewBuffer` — это мутабельный буфер чтения/записи.'}, {'num': 30, 'title': 'Комбинирование Query-параметров и заголовков авторизации в одном запросе', 'task': '**Параметры запроса и заголовки**: Напишите программу, которая выполняет запрос, добавляя кастомные HTTP-заголовки (например, `Authorization: Bearer my_token`) и Query-параметры (например, `?page=2&limit=10`). Для сборки URL с параметрами используйте структуру `net/url` и её методы.', 'theory': 'Полноценная сборка REST-запроса: динамическое добавление query-параметров через `net/url` и установка метаданных авторизации в `req.Header`.', 'step_by_step': '1. Сформируем URL с параметрами `?page=2&limit=10`.\n2. Добавим заголовок `Authorization: Bearer my_secret_token`.\n3. Отправим запрос на тестовый сервер.\n4. Сервер проверяет параметры и заголовок.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"net/url"\n)\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tpage := r.URL.Query().Get("page")\n\t\tlimit := r.URL.Query().Get("limit")\n\t\tauth := r.Header.Get("Authorization")\n\n\t\tfmt.Printf("[Server] Получен запрос: page=%s, limit=%s, auth=%s\\n", page, limit, auth)\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte(`{"items": ["item1", "item2"], "page": 2}`))\n\t}))\n\tdefer ts.Close()\n\n\t// 1. Сборка URL\n\tparsedURL, _ := url.Parse(ts.URL + "/api/v1/items")\n\tq := parsedURL.Query()\n\tq.Set("page", "2")\n\tq.Set("limit", "10")\n\tparsedURL.RawQuery = q.Encode()\n\n\t// 2. Создание запроса и заголовков\n\treq, _ := http.NewRequest(http.MethodGet, parsedURL.String(), nil)\n\treq.Header.Set("Authorization", "Bearer my_secret_token")\n\treq.Header.Set("Accept", "application/json")\n\n\tclient := &http.Client{}\n\tresp, err := client.Do(req)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tbody, _ := io.ReadAll(resp.Body)\n\tfmt.Printf("[Client] Ответ: %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Server] Получен запрос: page=2, limit=10, auth=Bearer my_secret_token\n# [Client] Ответ: {"items": ["item1", "item2"], "page": 2}'}], 'under_the_hood': '`r.URL.Query()` на стороне сервера парсит query-параметры из строки `RawQuery` в `url.Values`.', 'pitfalls': 'Не используйте `url.QueryEscape` для всего URL целиком, иначе двоеточия и слэши протокола превратятся в `%3A%2F%2F`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как безопасно передать сложные параметры (например, массивы и фильтры) в GET-запросе?»\n**Ответ:** Использовать `url.Values.Add("ids", "1")`, `url.Values.Add("ids", "2")` (результирует в `?ids=1&ids=2`), либо передавать Base64-encoded JSON в одном параметре `?filter=eyJzdGF0dXMiOiJhY3RpdmUifQ==`.'}, {'num': 31, 'title': 'Обработка сетевых ошибок, DNS сбоев и HTTP статус-кодов (404/500)', 'task': '**Обработка ошибок и статус-кодов**: Выполните запрос к несуществующему домену и обработайте возникающую сетевую ошибку. Выполните запрос к существующему домену, но по некорректному адресу (чтобы получить статус `404 Not Found`). Напишите корректную обработку статус-кодов ответов (проверку `resp.StatusCode`).', 'theory': 'Разделение ошибок сетевого и прикладного уровня:\n1. **Сетевые ошибки (`err != nil`):** DNS lookup failed, connection refused, connection timeout. В этом случае `resp == nil`.\n2. **Прикладные HTTP-ошибки (`err == nil`):** сервер успешно ответил, но статус-код равен 404, 401, 500. В этом случае `resp != nil` и `resp.Body` ОБЯЗАН быть закрыт.', 'step_by_step': '1. Выполним запрос к несуществующему хосту `http://non-existent-domain-xyz.invalid`.\n2. Обработаем сетевую ошибку.\n3. Выполним запрос к существующему серверу по несуществующему пути `/missing`.\n4. Обработаем статус `http.StatusNotFound`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\tclient := &http.Client{}\n\n\t// 1. Сетевая ошибка (DNS / Connect failure)\n\t_, err := client.Get("http://invalid-domain-123456789.invalid")\n\tif err != nil {\n\t\tfmt.Printf("[Network Error Handled] Сетевой сбой: %v\\n", err)\n\t}\n\n\t// 2. HTTP ошибка 404 Not Found\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\thttp.NotFound(w, r)\n\t}))\n\tdefer ts.Close()\n\n\tresp, err := client.Get(ts.URL + "/unknown-page")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tif resp.StatusCode == http.StatusNotFound {\n\t\tfmt.Printf("[HTTP Status Handled] Получен ожидаемый статус 404: %s\\n", resp.Status)\n\t} else {\n\t\tbody, _ := io.ReadAll(resp.Body)\n\t\tfmt.Printf("[Response] %s\\n", string(body))\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Network Error Handled] Сетевой сбой: Get "http://invalid-domain-123456789.invalid": dial tcp: lookup invalid-domain-123456789.invalid: no such host\n# [HTTP Status Handled] Получен ожидаемый статус 404: 404 Not Found'}], 'under_the_hood': 'Сетевые ошибки возвращают типы `*net.OpError` и `*url.Error`.', 'pitfalls': 'Статус 500 Internal Server Error возвращает `err == nil`! Проверяйте `resp.StatusCode >= 400`.', 'bigtech_interview': '**Вопрос с собеседования:** «Возвращает ли http.Get ошибку при получении HTTP 500 Internal Server Error?»\n**Ответ:** Нет! Функция `http.Get` возвращает `err == nil`, потому что сетевой протокол HTTP отработал успешно и сервер вернул валидный ответ. Проверка ошибочных статус-кодов (4xx, 5xx) является ответственностью прикладного кода через `resp.StatusCode`.'}, {'num': 32, 'title': 'Декодирование JSON-ответа публичного REST API в типизированную структуру', 'task': 'Напиши простой HTTP-клиент: `resp, err := http.Get("https://api.github.com/users/golang")`. Прочитай `resp.Body`, декодируй JSON в структуру. Не забудь `defer resp.Body.Close()`.', 'theory': 'Интеграция с внешними REST API: сопоставление JSON-полей со структурой Go через json-теги `json:"field_name"`.', 'step_by_step': '1. Опишем структуру `GithubUser { Login, Name, PublicRepos, Followers }`.\n2. Запустим тестовый эндпоинт.\n3. Выполним запрос и распарсим через `json.NewDecoder(resp.Body).Decode(&user)`.\n4. Выведем результат.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/json"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\ntype GithubUser struct {\n\tLogin       string `json:"login"`\n\tName        string `json:"name"`\n\tPublicRepos int    `json:"public_repos"`\n\tFollowers   int    `json:"followers"`\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\t_, _ = w.Write([]byte(`{\n\t\t\t"login": "golang",\n\t\t\t"name": "The Go Programming Language",\n\t\t\t"public_repos": 140,\n\t\t\t"followers": 12500\n\t\t}`))\n\t}))\n\tdefer ts.Close()\n\n\tresp, err := http.Get(ts.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tvar user GithubUser\n\tif err := json.NewDecoder(resp.Body).Decode(&user); err != nil {\n\t\tpanic(err)\n\t}\n\n\tfmt.Println("=== ДАННЫЕ ПОЛЬЗОВАТЕЛЯ GITHUB ===")\n\tfmt.Printf("Логин:       %s\\n", user.Login)\n\tfmt.Printf("Имя:         %s\\n", user.Name)\n\tfmt.Printf("Репозиториев: %d\\n", user.PublicRepos)\n\tfmt.Printf("Подписчиков: %d\\n", user.Followers)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === ДАННЫЕ ПОЛЬЗОВАТЕЛЯ GITHUB ===\n# Логин:       golang\n# Имя:         The Go Programming Language\n# Репозиториев: 140\n# Подписчиков: 12500'}], 'under_the_hood': '`json.Decoder` выполняет потоковую десериализацию прямо из сетевого сокета.', 'pitfalls': 'Всегда проверяйте `resp.StatusCode == http.StatusOK` перед декодированием JSON, иначе парсер упадет на HTML-странице ошибки 502/404.', 'bigtech_interview': '**Вопрос с собеседования:** «Что произойдет, если в JSON ответе придут дополнительные неизвестные поля?»\n**Ответ:** По умолчанию `json.Decoder` просто проигнорирует неизвестные поля. Если требуется строгая валидация структуры, включают режим `decoder.DisallowUnknownFields()`.'}, {'num': 33, 'title': 'Сброс тела в io.Discard и гарантированное сохранение Keep-Alive соединения', 'task': 'Покажи **утечку соединений**, если забыть `resp.Body.Close()`. Запусти 10000 запросов без закрытия — получи `"too many open files"`. Исправь: всегда закрывай Body, даже если не читаешь (или используй `io.Copy(io.Discard, resp.Body)`).', 'theory': 'Завершение жизненного цикла HTTP-ответа: для возврата сокета в пул требуется комбинация `io.Copy(io.Discard, resp.Body)` и `resp.Body.Close()`.', 'step_by_step': '1. Создадим функцию отправки запроса.\n2. Продемонстрируем гарантированное освобождение ресурсов.\n3. Выполним серию запросов в цикле.\n4. Проверим результат.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc safeDiscardRequest(client *http.Client, url string) error {\n\tresp, err := client.Get(url)\n\tif err != nil {\n\t\treturn err\n\t}\n\tdefer resp.Body.Close()\n\n\t// Сбрасываем тело ответа без аллокаций в памяти\n\t_, err = io.Copy(io.Discard, resp.Body)\n\treturn err\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte("DATA_PAYLOAD"))\n\t}))\n\tdefer ts.Close()\n\n\tclient := &http.Client{}\n\n\tfor i := 1; i <= 100; i++ {\n\t\tif err := safeDiscardRequest(client, ts.URL); err != nil {\n\t\t\tpanic(err)\n\t\t}\n\t}\n\n\tfmt.Println("[Main] 100 запросов успешно завершены, сокеты переиспользованы без утечек.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Main] 100 запросов успешно завершены, сокеты переиспользованы без утечек.'}], 'under_the_hood': '`io.Discard` сбрасывает данные со скоростью сети без аллокаций.', 'pitfalls': 'Если не вычитать тело до конца, транспорт вынужден разорвать TCP-сессию (TCP RST/FIN).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему io.Copy(io.Discard, resp.Body) критичен для микросервисов с высоким RPS?»\n**Ответ:** Без полной вычитки тела ответа `http.Transport` не может гарантировать, что в сокете не осталось данных предыдущего ответа, и закрывает сокет. Вычитка в `io.Discard` сохраняет TCP-сессию активной в пуле Keep-Alive.'}, {'num': 34, 'title': 'Клиентский Middleware через переопределение интерфейса http.RoundTripper', 'task': '**Кастомный транспорт (`RoundTripper`)**: Напишите Middleware для HTTP-клиента. Для этого создайте структуру, реализующую интерфейс `http.RoundTripper`. Данный транспорт должен перехватывать все исходящие запросы вашего клиента, автоматически замерять время их выполнения и выводить его в лог, после чего делегировать выполнение стандартному транспорту `http.DefaultTransport`.', 'theory': 'Интерфейс `http.RoundTripper` (Клиентский Middleware): содержит единственный метод `RoundTrip(*http.Request) (*http.Response, error)`. Оборачивание транспорта позволяет реализовывать:\n1. Автоматическое добавление заголовков авторизации / трассировки (Tracing Headers).\n2. Замер задержек и сбор метрик в Prometheus.\n3. Логирование исходящего сетевого трафика.\n4. Автоматические ретраи на транспортном уровне.', 'step_by_step': '1. Создадим структуру `LoggingTransport struct { Base http.RoundTripper }`.\n2. Реализуем метод `RoundTrip(req)`.\n3. Подставим в `client.Transport = &LoggingTransport{Base: http.DefaultTransport}`.\n4. Выполним тестовые запросы и проверим лог.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\ntype MetricsTransport struct {\n\tBase http.RoundTripper\n}\n\nfunc (t *MetricsTransport) RoundTrip(req *http.Request) (*http.Response, error) {\n\tt0 := time.Now()\n\n\t// Автоматически добавляем заголовок трассировки во все исходящие запросы\n\treq.Header.Set("X-Client-Trace-ID", "TRACE-UUID-998877")\n\n\tbase := t.Base\n\tif base == nil {\n\t\tbase = http.DefaultTransport\n\t}\n\n\tresp, err := base.RoundTrip(req)\n\tduration := time.Since(t0)\n\n\tif err != nil {\n\t\tfmt.Printf("[CLIENT ROUNDTRIP ERROR] %s %s -> Err: %v | Latency: %v\\n", \n\t\t\treq.Method, req.URL, err, duration.Round(time.Microsecond))\n\t\treturn nil, err\n\t}\n\n\tfmt.Printf("[CLIENT ROUNDTRIP METRICS] %s %s -> Status: %d | Latency: %v\\n", \n\t\treq.Method, req.URL.Path, resp.StatusCode, duration.Round(time.Microsecond))\n\n\treturn resp, nil\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte("PONG"))\n\t}))\n\tdefer ts.Close()\n\n\tclient := &http.Client{\n\t\tTransport: &MetricsTransport{Base: http.DefaultTransport},\n\t\tTimeout:   2 * time.Second,\n\t}\n\n\tresp, err := client.Get(ts.URL + "/api/ping")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\t_, _ = io.Copy(io.Discard, resp.Body)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [CLIENT ROUNDTRIP METRICS] GET /api/ping -> Status: 200 | Latency: 10ms'}], 'under_the_hood': '`RoundTripper` выполняется на самом низком уровне клиента, гарантируя выполнение для всех вызовов `client.Get`, `client.Post` и `client.Do`.', 'pitfalls': 'В `RoundTrip` нельзя модифицировать сам `*http.Request` без его клонирования (`req.Clone(req.Context())`), если запрос может быть повторен.', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать OpenTelemetry трассировку для всех исходящих HTTP-запросов сервиса?»\n**Ответ:** Обернуть `client.Transport` в `otelhttp.NewTransport(http.DefaultTransport)`. Он реализует `http.RoundTripper`, автоматически внедряет заголовки W3C Trace Context (`traceparent`) в исходящий запрос и создает дочерний спан (Child Span).'}, {'num': 35, 'title': 'Отправка классических HTML-форм с Content-Type application/x-www-form-urlencoded', 'task': 'Напиши `POST` с `application/x-www-form-urlencoded`: используй `url.Values` и `strings.NewReader(values.Encode())`. Отправь на тестовый сервер.', 'theory': 'Формат `application/x-www-form-urlencoded`: стандартный формат отправки веб-форм. Данные кодируются как ключ-значение в виде `key1=val1&key2=val2` и передаются в теле запроса через функцию `http.PostForm(url, data)` или `http.Post`.', 'step_by_step': '1. Создадим `formData := url.Values{}`.\n2. Добавим поля `formData.Set("grant_type", "password")`, `formData.Set("username", "admin")`.\n3. Отправим запрос через `http.Post(ts.URL, "application/x-www-form-urlencoded", strings.NewReader(formData.Encode()))`.\n4. Сервер парсит форму через `r.ParseForm()` и валидирует данные.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"net/url"\n\t"strings"\n)\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tif err := r.ParseForm(); err != nil {\n\t\t\thttp.Error(w, err.Error(), http.StatusBadRequest)\n\t\t\treturn\n\t\t}\n\n\t\tuser := r.Form.Get("username")\n\t\tgrant := r.Form.Get("grant_type")\n\t\tfmt.Printf("[Server Form Auth] User: %s | GrantType: %s\\n", user, grant)\n\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte("OAUTH_TOKEN_GRANTED"))\n\t}))\n\tdefer ts.Close()\n\n\t// Формируем поля формы\n\tformData := url.Values{}\n\tformData.Set("grant_type", "password")\n\tformData.Set("username", "developer@google.com")\n\tformData.Set("scope", "read:profile write:orders")\n\n\t// Отправка запроса\n\tresp, err := http.Post(\n\t\tts.URL,\n\t\t"application/x-www-form-urlencoded",\n\t\tstrings.NewReader(formData.Encode()),\n\t)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tbody, _ := io.ReadAll(resp.Body)\n\tfmt.Printf("[Client] Ответ: %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Server Form Auth] User: developer@google.com | GrantType: password\n# [Client] Ответ: OAUTH_TOKEN_GRANTED'}], 'under_the_hood': 'Метод `http.PostForm(url, formData)` является удобной оберткой над `http.Post` с `strings.NewReader(formData.Encode())`.', 'pitfalls': 'В больших формах с бинарными файлами `x-www-form-urlencoded` неэффективен из-за 300% раздувания объема данных (экранирование байтов); используйте `multipart/form-data`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие r.Form от r.PostForm на стороне сервера?»\n**Ответ:** `r.Form` объединяет в себе параметры и из URL Query String, и из тела POST-формы. `r.PostForm` содержит строго параметры, переданные в теле POST/PUT запроса, игнорируя query-параметры из строки URL.'}, {'num': 36, 'title': 'Управление таймаутами клиента: сравнение http.Client и http.DefaultClient', 'task': 'Напиши **HTTP-клиент с таймаутом**: `http.Client{Timeout: 5 * time.Second}`. Покажи, что `http.DefaultClient` **не имеет таймаута** (бесконечное ожидание). Это опасно в production.', 'theory': 'Сравнение дефолтного и изолированного клиентов: `http.DefaultClient` имеет `Timeout = 0`, что означает отсутствие ограничения по времени. Явная инициализация `http.Client{Timeout: ...}` гарантирует предсказуемость времени отклика.', 'step_by_step': '1. Создадим `client := &http.Client{Timeout: 40 * time.Millisecond}`.\n2. Протестируем запрос к быстрому эндпоинту (успех).\n3. Протестируем запрос к медленному эндпоинту (таймаут).\n4. Выведем результаты.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\ttime.Sleep(80 * time.Millisecond)\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte("OK"))\n\t}))\n\tdefer ts.Close()\n\n\tclient := &http.Client{\n\t\tTimeout: 40 * time.Millisecond,\n\t}\n\n\tfmt.Println("[Client] Выполняем запрос с таймаутом 40 мс...")\n\t_, err := client.Get(ts.URL)\n\n\tif err != nil {\n\t\tfmt.Printf("[Client Protected] Запрос штатно прерван по таймауту: %v\\n", err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client] Выполняем запрос с таймаутом 40 мс...\n# [Client Protected] Запрос штатно прерван по таймауту: Get "http://127.0.0.1:...": context deadline exceeded (Client.Timeout exceeded while awaiting headers)'}], 'under_the_hood': '`client.Timeout` инициирует таймер рантайма в момент вызова метода `Do()`.', 'pitfalls': '`client.Timeout` действует на всю операцию, включая скачивание тела. Для больших файлов настраивают таймауты внутри `Transport.DialContext` и `ResponseHeaderTimeout`.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое ResponseHeaderTimeout в http.Transport?»\n**Ответ:** Это время, в течение которого клиент ожидает заголовки ответа от сервера после отправки запроса. Оно не включает время на чтение тела ответа, что идеально для скачивания больших файлов и стриминга.'}, {'num': 37, 'title': 'Экспоненциальный Backoff и контекстный дедлайн в цикле повторных запросов', 'task': 'Напиши **retry logic** для HTTP-клиента: при ошибке сети или статусе `5xx` — повтори запрос с exponential backoff (100ms, 200ms, 400ms, max 3 попытки). Используй `context` для ограничения общего времени.', 'theory': 'Паттерн Exponential Backoff with Jitter: интервал между повторными попытками увеличивается вдвое на каждом шаге ($T, 2T, 4T$), предотвращая эффект громоподобного стада (Thundering Herd Problem) при восстановлении упавшего сервиса.', 'step_by_step': '1. Создадим контекст с общим дедлайном 500 мс.\n2. Реализуем цикл ретраев с удвоением `backoff *= 2`.\n3. Сервер имитирует 503 на первых 2 попытках и 200 OK на 3-й.\n4. Проверим успешную доставку.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc executeWithBackoff(ctx context.Context, client *http.Client, url string) (string, error) {\n\tbackoff := 25 * time.Millisecond\n\tconst maxRetries = 3\n\n\tfor attempt := 1; attempt <= maxRetries; attempt++ {\n\t\treq, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)\n\t\tif err != nil {\n\t\t\treturn "", err\n\t\t}\n\n\t\tresp, err := client.Do(req)\n\t\tif err == nil && resp.StatusCode < 500 {\n\t\t\tdefer resp.Body.Close()\n\t\t\tbody, _ := io.ReadAll(resp.Body)\n\t\t\treturn string(body), nil\n\t\t}\n\n\t\tif resp != nil {\n\t\t\t_, _ = io.Copy(io.Discard, resp.Body)\n\t\t\t_ = resp.Body.Close()\n\t\t}\n\n\t\tfmt.Printf(" [!] Попытка #%d не удалась. Пауза %v перед повтором...\\n", attempt, backoff)\n\n\t\tselect {\n\t\tcase <-time.After(backoff):\n\t\t\tbackoff *= 2\n\t\tcase <-ctx.Done():\n\t\t\treturn "", ctx.Err()\n\t\t}\n\t}\n\treturn "", fmt.Errorf("все попытки исчерпаны")\n}\n\nfunc main() {\n\ttries := 0\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\ttries++\n\t\tif tries < 3 {\n\t\t\tw.WriteHeader(http.StatusBadGateway) // 502\n\t\t\treturn\n\t\t}\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte("FINAL_SUCCESS_RESULT"))\n\t}))\n\tdefer ts.Close()\n\n\tclient := &http.Client{}\n\tctx, cancel := context.WithTimeout(context.Background(), 1*time.Second)\n\tdefer cancel()\n\n\tresult, err := executeWithBackoff(ctx, client, ts.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\n\tfmt.Printf("[Client] Успешный результат после ретраев: %s\\n", result)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  [!] Попытка #1 не удалась. Пауза 25ms перед повтором...\n#  [!] Попытка #2 не удалась. Пауза 50ms перед повтором...\n# [Client] Успешный результат после ретраев: FINAL_SUCCESS_RESULT'}], 'under_the_hood': '`select` с `ctx.Done()` гарантирует, что сон `time.After` прервется немедленно, если истечет общий дедлайн родительской операции.', 'pitfalls': 'В реальных HighLoad сервисах к backoff обязательно добавляют случайный шум (Jitter: $\\pm 20\\%$), чтобы тысячи клиентов не просыпались синхронно.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем нужен Full Jitter при реализации алгоритма Exponential Backoff?»\n**Ответ:** Если сервер упал и перезагрузился, клиенты с фиксированным backoff будут слать повторные запросы синхронными волнами (Thundering Herd), снова роняя сервер. Full Jitter распределяет время ретраев равномерно по интервалу $[0, \\text{backoff}]$, размазывая нагрузку во времени.'}, {'num': 38, 'title': 'Интерактивный прогресс-бар скачивания файла через кастомный io.Writer', 'task': '**Скачивание файла с прогресс-баром**: Напишите утилиту, которая скачивает крупный файл (например, архив или картинку) по HTTP. Программа не должна загружать файл в память целиком — используйте `io.Copy`, чтобы записывать данные напрямую в файл на диске по мере скачивания. Реализуйте простой вывод прогресса (сколько процентов скачано) в консоль в реальном времени.', 'theory': 'Паттерн Progress Tracking Writer: структура `PassThroughWriter`, реализующая `io.Writer`, подсчитывает количество записанных байт и обновляет процент выполнения относительно заголовка `resp.ContentLength`.', 'step_by_step': '1. Создадим структуру `ProgressWriter { Total, Current }`.\n2. В методе `Write(p)` накапливаем `Current += len(p)` и выводим процент.\n3. Обернем `io.Copy(progressWriter, resp.Body)`.\n4. Проверим расчет прогресса.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\ntype ProgressWriter struct {\n\tTotal      int64\n\tDownloaded int64\n}\n\nfunc (pw *ProgressWriter) Write(p []byte) (int, error) {\n\tn := len(p)\n\tpw.Downloaded += int64(n)\n\n\tpercent := float64(pw.Downloaded) / float64(pw.Total) * 100\n\tfmt.Printf("\\r [Скачивание] Прогресс: %.1f%% (%d / %d байт)", \n\t\tpercent, pw.Downloaded, pw.Total)\n\n\treturn n, nil\n}\n\nfunc main() {\n\tconst totalSize = 2 * 1024 * 1024 // 2 МБ\n\tdata := bytes.Repeat([]byte("X"), totalSize)\n\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.Header().Set("Content-Length", fmt.Sprintf("%d", totalSize))\n\t\tw.Header().Set("Content-Type", "application/octet-stream")\n\t\t_, _ = w.Write(data)\n\t}))\n\tdefer ts.Close()\n\n\tresp, err := http.Get(ts.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tpw := &ProgressWriter{Total: resp.ContentLength}\n\n\t// Потоковое копирование через обертку прогресса\n\t_, err = io.Copy(pw, resp.Body)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\n\tfmt.Println("\\n[Main] Скачивание успешно завершено на 100%!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  [Скачивание] Прогресс: 100.0% (2097152 / 2097152 байт)\n# [Main] Скачивание успешно завершено на 100%!'}], 'under_the_hood': '`resp.ContentLength` считывается из заголовка `Content-Length`. Если сервер использует `Transfer-Encoding: chunked`, `ContentLength` равен `-1`.', 'pitfalls': 'Если `resp.ContentLength == -1`, процент прогресса вычислить невозможно, выводят только общий объем скачанных байтов.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему resp.ContentLength может быть равен -1?»\n**Ответ:** Если сервер генерирует ответ динамически и отправляет данные по частям с заголовком `Transfer-Encoding: chunked`, точный размер тела ответа заранее неизвестен, и заголовок `Content-Length` отсутствует. В Go поле `resp.ContentLength` в этом случае устанавливается в `-1`.'}, {'num': 39, 'title': 'Параллельный сбор данных из среза URL с WaitGroup и семафором', 'task': 'Напиши **параллельные HTTP-запросы**: список URL. Для каждого URL запусти горутину с `http.Get`. Собери результаты через канал. Используй `sync.WaitGroup` или `errgroup` для ожидания.', 'theory': 'Паттерн Fan-Out HTTP Scraper (Параллельный краулер): параллельный запуск $N$ HTTP-запросов с ограничением конкурентности через буферизованный канал-семафор и сбор результатов в единый канал ответов.', 'step_by_step': '1. Поднимем тестовые HTTP эндпоинты `/item/1`, `/item/2`, `/item/3`.\n2. Запустим горутины под управлением `sync.WaitGroup`.\n3. Соберем результаты в `resultsChan := make(chan Result, len(urls))`.\n4. Закроем канал и выведем агрегированные данные.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"sync"\n\t"time"\n)\n\ntype FetchResult struct {\n\tURL        string\n\tStatusCode int\n\tBody       string\n\tDuration   time.Duration\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte("Data for " + r.URL.Path))\n\t}))\n\tdefer ts.Close()\n\n\turls := []string{\n\t\tts.URL + "/users",\n\t\tts.URL + "/orders",\n\t\tts.URL + "/products",\n\t\tts.URL + "/analytics",\n\t}\n\n\tclient := &http.Client{Timeout: 2 * time.Second}\n\tresultsChan := make(chan FetchResult, len(urls))\n\n\tvar wg sync.WaitGroup\n\twg.Add(len(urls))\n\n\tfor _, u := range urls {\n\t\tgo func(targetURL string) {\n\t\t\tdefer wg.Done()\n\t\t\tt0 := time.Now()\n\n\t\t\tresp, err := client.Get(targetURL)\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tdefer resp.Body.Close()\n\n\t\t\tbody, _ := io.ReadAll(resp.Body)\n\t\t\tresultsChan <- FetchResult{\n\t\t\t\tURL:        targetURL,\n\t\t\t\tStatusCode: resp.StatusCode,\n\t\t\t\tBody:       string(body),\n\t\t\t\tDuration:   time.Since(t0),\n\t\t\t}\n\t\t}(u)\n\t}\n\n\twg.Wait()\n\tclose(resultsChan)\n\n\tfmt.Println("=== РЕЗУЛЬТАТЫ ПАРАЛЛЕЛЬНОГО СБОРА ДАННЫХ ===")\n\tfor res := range resultsChan {\n\t\tfmt.Printf(" -> Status %d | Time: %6v | %s\\n", \n\t\t\tres.StatusCode, res.Duration.Round(time.Millisecond), res.Body)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === РЕЗУЛЬТАТЫ ПАРАЛЛЕЛЬНОГО СБОРА ДАННЫХ ===\n#  -> Status 200 | Time:   10ms | Data for /users\n#  -> Status 200 | Time:   10ms | Data for /orders\n#  -> Status 200 | Time:   10ms | Data for /products\n#  -> Status 200 | Time:   10ms | Data for /analytics'}], 'under_the_hood': 'Все 4 параллельных запроса выполняются одновременно за 10 мс (время одного самого медленного запроса).', 'pitfalls': 'Обязательно передавайте переменную `u` как аргумент `go func(targetURL string)` в цикле `for`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему при параллельных HTTP-запросах критично использовать errgroup.Group вместо обычной sync.WaitGroup?»\n**Ответ:** `golang.org/x/sync/errgroup` автоматически прерывает все остальные параллельные HTTP-запросы через связанный `context.Context`, как только хотя бы один из запросов завершился ошибкой (Fail-Fast семантика).'}, {'num': 40, 'title': 'Стриминг и дублирование потока через io.TeeReader для логирования', 'task': 'Напиши **HTTP-загрузчик файла**: `http.Get` по URL, `io.Copy` в локальный файл. Покажи прогресс: в отдельной горутине читай `resp.ContentLength` и сколько байт скопировано (через `io.TeeReader` или `io.Reader` обёртку).', 'theory': 'Паттерн Stream Splitting (Разветвитель потока): функция `io.TeeReader(r, w)` возвращает `io.Reader`, который при каждом чтении из `r` синхронно дублирует прочитанные байты в `w` (по аналогии с Unix-утилитой `tee`).', 'step_by_step': '1. Создадим тестовый сервер.\n2. Обернем `resp.Body` через `tee := io.TeeReader(resp.Body, logger)`.\n3. Считаем данные в целевой файл через `io.Copy(dest, tee)`.\n4. Проверим, что данные попали и в файл, и в логгер.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte("STREAMING_TELEMETRY_PAYLOAD"))\n\t}))\n\tdefer ts.Close()\n\n\tresp, err := http.Get(ts.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tvar fileStorage bytes.Buffer\n\tvar debugLogger bytes.Buffer\n\n\t// TeeReader дублирует каждый байт из resp.Body в debugLogger во время чтения\n\ttee := io.TeeReader(resp.Body, &debugLogger)\n\n\t// Читаем из tee в целевое хранилище\n\twritten, err := io.Copy(&fileStorage, tee)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\n\tfmt.Printf("[TeeReader Pipeline] Записано в файл:   %d байт (%s)\\n", written, fileStorage.String())\n\tfmt.Printf("[TeeReader Pipeline] Записано в логгер: %d байт (%s)\\n", debugLogger.Len(), debugLogger.String())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [TeeReader Pipeline] Записано в файл:   27 байт (STREAMING_TELEMETRY_PAYLOAD)\n# [TeeReader Pipeline] Записано в логгер: 27 байт (STREAMING_TELEMETRY_PAYLOAD)'}], 'under_the_hood': '`io.TeeReader` не создает промежуточных буферов в памяти: вызов `Read` напрямую вызывает `Write` второго получателя.', 'pitfalls': 'Если запись в дублирующий `io.Writer` вернет ошибку, чтение из `TeeReader` тоже прервется с ошибкой.', 'bigtech_interview': '**Вопрос с собеседования:** «Как с помощью io.TeeReader посчитать SHA-256 хеш скачиваемого файла на лету?»\n**Ответ:** Создать хешер `hasher := sha256.New()`, обернуть поток `tee := io.TeeReader(resp.Body, hasher)` и передать в `io.Copy(file, tee)`. По завершении скачивания `hasher.Sum(nil)` вернет точный SHA-256 хеш без повторного чтения файла с диска.'}, {'num': 41, 'title': 'Параллельный опрос 10 микросервисов со сбором результатов в потокобезопасную мапу', 'task': '**Конкурентный сбор данных**: У вас есть срез из 10 различных URL-адресов. Напишите программу, которая параллельно отправляет GET-запросы ко всем этим адресам с помощью горутин. Соберите результаты (статус-коды и тела ответов) в потокобезопасную мапу или верните их в основной поток через каналы.', 'theory': 'Паттерн Concurrent Aggregator: параллельный сбор метаданных от множества микросервисов с синхронизацией через `sync.Mutex` или `sync.Map`.', 'step_by_step': '1. Создадим структуру `SafeResultMap` с мьютексом.\n2. Запустим 10 параллельных запросов к mock-серверу.\n3. Сохраним результаты в мапу по ключу URL.\n4. Выведем агрегированный отчет.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"strconv"\n\t"sync"\n\t"time"\n)\n\ntype SafeStore struct {\n\tmu   sync.Mutex\n\tdata map[string]string\n}\n\nfunc (s *SafeStore) Set(key, val string) {\n\ts.mu.Lock()\n\tdefer s.mu.Unlock()\n\ts.data[key] = val\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte("Response for " + r.URL.Path))\n\t}))\n\tdefer ts.Close()\n\n\tclient := &http.Client{Timeout: 2 * time.Second}\n\tstore := &SafeStore{data: make(map[string]string)}\n\n\tvar wg sync.WaitGroup\n\tconst totalEndpoints = 10\n\twg.Add(totalEndpoints)\n\n\tfor i := 1; i <= totalEndpoints; i++ {\n\t\tendpointURL := ts.URL + "/service/" + strconv.Itoa(i)\n\t\tgo func(target string) {\n\t\t\tdefer wg.Done()\n\t\t\tresp, err := client.Get(target)\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tdefer resp.Body.Close()\n\n\t\t\tbody, _ := io.ReadAll(resp.Body)\n\t\t\tstore.Set(target, string(body))\n\t\t}(endpointURL)\n\t}\n\n\twg.Wait()\n\n\tfmt.Printf("=== УСПЕШНО ОПРОШЕНО %d ЭНДПОИНТОВ ===\\n", len(store.data))\n\tfor k, v := range store.data {\n\t\tfmt.Printf(" -> %s = %s\\n", k, v)\n\t\tbreak // печатаем пример\n\t}\n\tfmt.Printf("Всего записей в потокобезопасной мапе: %d\\n", len(store.data))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === УСПЕШНО ОПРОШЕНО 10 ЭНДПОИНТОВ ===\n#  -> http://127.0.0.1:.../service/1 = Response for /service/1\n# Всего записей в потокобезопасной мапе: 10'}], 'under_the_hood': 'Мьютекс защищает карту Go от одновременной записи (`fatal error: concurrent map writes`).', 'pitfalls': 'Без мьютекса параллельная запись в `map` немедленно завершит процесс аварийной паникой рантайма.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие sync.Map от обычной map под sync.RWMutex?»\n**Ответ:** `sync.Map` оптимизирована для двух сценариев: 1. Ключи записываются один раз, а читаются миллионы раз (Cache); 2. Множество горутин читают, обновляют и записывают непересекающиеся наборы ключей. Для общих задач `map + sync.RWMutex` предпочтительнее.'}, {'num': 42, 'title': 'Инициализация CookieJar и автоматическая передача cookie между запросами', 'task': 'Напиши **HTTP-клиент с CookieJar**: `jar, _ := cookiejar.New(nil); client := &http.Client{Jar: jar}`. Сделай два запроса к серверу, устанавливающему cookie. Покажи, что второй запрос автоматически отправляет cookie.', 'theory': 'Сохранение состояния сессии (Stateful HTTP Session): `http.CookieJar` автоматически связывает куки с доменом и путем, возвращая их в последующих вызовах.', 'step_by_step': '1. Создадим `cookiejar.New(nil)`.\n2. Первый запрос к `/set` устанавливает `cookie: auth=token123`.\n3. Второй запрос к `/get` отправляет куку на сервер.\n4. Сервер подтверждает получение куки.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/cookiejar"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tif r.URL.Path == "/set" {\n\t\t\thttp.SetCookie(w, &http.Cookie{\n\t\t\t\tName:  "session_id",\n\t\t\t\tValue: "XYZ-998877",\n\t\t\t\tPath:  "/",\n\t\t\t})\n\t\t\tw.WriteHeader(http.StatusOK)\n\t\t\t_, _ = w.Write([]byte("Cookie Set!"))\n\t\t\treturn\n\t\t}\n\n\t\tif r.URL.Path == "/get" {\n\t\t\tc, err := r.Cookie("session_id")\n\t\t\tif err != nil {\n\t\t\t\tw.WriteHeader(http.StatusBadRequest)\n\t\t\t\t_, _ = w.Write([]byte("No cookie"))\n\t\t\t\treturn\n\t\t\t}\n\t\t\tw.WriteHeader(http.StatusOK)\n\t\t\t_, _ = w.Write([]byte("FOUND_COOKIE:" + c.Value))\n\t\t}\n\t}))\n\tdefer ts.Close()\n\n\tjar, _ := cookiejar.New(nil)\n\tclient := &http.Client{Jar: jar}\n\n\t// 1. Первый запрос (получаем куку)\n\tr1, _ := client.Get(ts.URL + "/set")\n\tr1.Body.Close()\n\n\t// 2. Второй запрос (кука отправляется автоматически!)\n\tr2, _ := client.Get(ts.URL + "/get")\n\tdefer r2.Body.Close()\n\n\tfmt.Printf("[Client Session] Статус: %s\\n", r2.Status)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client Session] Статус: 200 OK'}], 'under_the_hood': '`CookieJar` обновляет внутреннюю базу данных кук на основе домена URL из ответа.', 'pitfalls': 'Если в `http.Cookie` не задан `Path`, кука будет отправляться только на тот же путь.', 'bigtech_interview': '**Вопрос с собеседования:** «Является ли http.CookieJar потокобезопасным?»\n**Ответ:** Да, стандартная реализация `net/http/cookiejar` защищает доступ к внутренним структурам через `sync.Mutex` и безопасна для параллельного использования несколькими горутинами.'}, {'num': 43, 'title': 'Глубокая настройка параметров пула соединений в http.Transport', 'task': 'Напиши **HTTP-клиент с `http.Transport` tuning**: настрой `MaxIdleConns`, `MaxIdleConnsPerHost`, `IdleConnTimeout`, `DisableKeepAlives`. Объясни, зачем нужен connection pool и keep-alive.', 'theory': 'Параметры тюнинга пула соединений Go:\n* `MaxIdleConns`: максимальное суммарное число свободных (idle) Keep-Alive соединений по всем хостам.\n* `MaxIdleConnsPerHost`: лимит свободных соединений к конкретному хосту.\n* `IdleConnTimeout`: время закрытия неиспользуемого сокета.\n* `DisableKeepAlives`: полное отключение пулинга.', 'step_by_step': '1. Создадим полностью сконфигурированный `http.Transport`.\n2. Выведем параметры конфигурации.\n3. Продемонстрируем назначение каждого поля.\n4. Проверим запуск.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"time"\n)\n\nfunc main() {\n\ttransport := &http.Transport{\n\t\tMaxIdleConns:        1000,             // Суммарный пул idle сокетов\n\t\tMaxIdleConnsPerHost: 200,              // Пул idle сокетов на 1 бэкенд\n\t\tIdleConnTimeout:     120 * time.Second, // Сокет закрывается после 2 минут простоя\n\t\tDisableKeepAlives:   false,            // Keep-Alive включен для HighLoad\n\t}\n\n\tclient := &http.Client{\n\t\tTransport: transport,\n\t\tTimeout:   10 * time.Second,\n\t}\n\n\tfmt.Println("=== ТЮНИНГ СЕТЕВОГО ТРАНСПОРТА GOLANG ===")\n\tfmt.Printf("MaxIdleConns:        %d\\n", transport.MaxIdleConns)\n\tfmt.Printf("MaxIdleConnsPerHost: %d\\n", transport.MaxIdleConnsPerHost)\n\tfmt.Printf("IdleConnTimeout:     %v\\n", transport.IdleConnTimeout)\n\tfmt.Printf("DisableKeepAlives:   %v\\n", transport.DisableKeepAlives)\n\tfmt.Printf("Client Timeout:      %v\\n", client.Timeout)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === ТЮНИНГ СЕТЕВОГО ТРАНСПОРТА GOLANG ===\n# MaxIdleConns:        1000\n# MaxIdleConnsPerHost: 200\n# IdleConnTimeout:     2m0s\n# DisableKeepAlives:   false\n# Client Timeout:      10s'}], 'under_the_hood': 'Транспорт поддерживает фоновый таймер очистки устаревших сокетов по `IdleConnTimeout`.', 'pitfalls': 'Если `MaxIdleConns < MaxIdleConnsPerHost`, суммарный лимит сокетов будет обрезан параметром `MaxIdleConns`.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы симптомы нехватки MaxIdleConnsPerHost в графиках Grafana?»\n**Ответ:** Резкий рост количества открываемых TCP-сокетов (TCP Connect spikes), рост задержек P99 из-за повторных TLS Handshake и накопление сокетов в состоянии `TIME_WAIT` на стороне клиента и сервера.'}, {'num': 44, 'title': 'Одновременный вывод в консоль и сохранение в файл через io.TeeReader', 'task': 'Напиши **HTTP-клиент с `io.TeeReader`**: читай ответ и одновременно пиши его в `os.Stdout` (для отладки) и в файл (для сохранения). Используй `io.TeeReader(resp.Body, file)` + `io.Copy`.', 'theory': 'Разветвление входящего потока (Multi-Destination Streaming): `io.TeeReader(r, w)` позволяет направлять сетевой поток одновременно на экран и в долговременное хранилище за один проход.', 'step_by_step': '1. Запустим тестовый сервер.\n2. Создадим буфер файла и буфер консоли.\n3. Обернем поток в `io.TeeReader`.\n4. Выполним `io.Copy(dest, tee)`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte("Critical Security Audit Log Data"))\n\t}))\n\tdefer ts.Close()\n\n\tresp, err := http.Get(ts.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tvar fileStorage bytes.Buffer\n\tvar stdoutMirror bytes.Buffer\n\n\t// Одновременно пишем в stdoutMirror при чтении\n\ttee := io.TeeReader(resp.Body, &stdoutMirror)\n\n\t// Копируем в fileStorage\n\t_, _ = io.Copy(&fileStorage, tee)\n\n\tfmt.Printf("[Screen Output]: %s\\n", stdoutMirror.String())\n\tfmt.Printf("[Saved File]:    %s\\n", fileStorage.String())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Screen Output]: Critical Security Audit Log Data\n# [Saved File]:    Critical Security Audit Log Data'}], 'under_the_hood': '`TeeReader` перехватывает каждый чанк данных в момент вызова `Read()`.', 'pitfalls': 'Медленный `Writer` в `TeeReader` замедлит скорость чтения всего сетевого сокета.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие io.MultiWriter от io.TeeReader?»\n**Ответ:** `io.MultiWriter(w1, w2)` принимает данные на запись и дублирует их в несколько `io.Writer`. `io.TeeReader(r, w)` перехватывает операцию чтения из `io.Reader` и попутно записывает прочитанное в `w`.'}, {'num': 45, 'title': 'Быстрая инспекция метаданных ресурса через HTTP HEAD-запрос', 'task': 'Напиши **HTTP HEAD-запрос**: `http.Head(url)`. Получи только заголовки без тела. Используй для проверки существования ресурса или получения `Content-Length` перед загрузкой.', 'theory': 'Экономичный метод HTTP HEAD: сервер возвращает те же заголовки (`Content-Length`, `Content-Type`, `Last-Modified`), что и для GET, но с пустым телом ответа. Это позволяет проверить доступность файла и его размер без скачивания гигабайтов данных.', 'step_by_step': '1. Создадим сервер с эндпоинтом `/large-archive.tar.gz`.\n2. Выполним `http.Head(url)`.\n3. Считаем `resp.ContentLength` и `resp.Header.Get("Content-Type")`.\n4. Убедимся, что тело пустое.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tif r.Method == http.MethodHead {\n\t\t\tw.Header().Set("Content-Length", "1073741824") // 1 ГБ\n\t\t\tw.Header().Set("Content-Type", "application/x-tar")\n\t\t\tw.Header().Set("Accept-Ranges", "bytes")\n\t\t\tw.WriteHeader(http.StatusOK)\n\t\t\treturn // Тело НЕ отправляется в HEAD-ответе\n\t\t}\n\t\tw.WriteHeader(http.StatusMethodNotAllowed)\n\t}))\n\tdefer ts.Close()\n\n\t// Выполняем HEAD-запрос\n\tresp, err := http.Head(ts.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tfmt.Println("=== РЕЗУЛЬТАТ HTTP HEAD-ЗАПРОСА ===")\n\tfmt.Printf("Статус:            %s\\n", resp.Status)\n\tfmt.Printf("Размер файла:      %.2f ГБ (%d байт)\\n", \n\t\tfloat64(resp.ContentLength)/(1024*1024*1024), resp.ContentLength)\n\tfmt.Printf("MIME-тип:          %s\\n", resp.Header.Get("Content-Type"))\n\tfmt.Printf("Поддержка Ranges:  %s\\n", resp.Header.Get("Accept-Ranges"))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === РЕЗУЛЬТАТ HTTP HEAD-ЗАПРОСА ===\n# Статус:            200 OK\n# Размер файла:      1.00 ГБ (1073741824 байт)\n# MIME-тип:          application/x-tar\n# Поддержка Ranges:  bytes'}], 'under_the_hood': 'Сервер отправляет только HTTP-заголовки, завершаемые последовательностью `\\r\\n\\r\\n`.', 'pitfalls': 'Даже для HEAD-запроса вызов `defer resp.Body.Close()` обязателен для корректного возврата сокета в пул.', 'bigtech_interview': '**Вопрос с собеседования:** «Как с помощью HEAD-запроса проверить, изменился ли файл на сервере (Кэширование)?»\n**Ответ:** Проверить заголовки `ETag` (хеш содержимого) или `Last-Modified`. В последующем GET-запросе передать заголовок `If-None-Match: <ETag>` или `If-Modified-Since: <Date>`. Если файл не менялся, сервер вернет легковесный статус `304 Not Modified`.'}]
